package expo.modules.recognitioncpu;
import java.io.*;
import java.util.*;
import static expo.modules.recognitioncpu.CameraMatrixPlan.*;

/** Eight immutable V2 rows. A failed or uncertain row is consumed, never replaced. */
public final class CameraOrientationStore {
  public static final int RECORD=4096,JOURNAL=128*1024;
  private final File root;private final CameraProofStore.IO io;private final String source,apk,process;
  public CameraOrientationStore(File root,CameraProofStore.IO io,String source,String apk,String process,boolean fresh)throws Exception{
    this.root=root;this.io=io;this.source=hash(source);this.apk=hash(apk);this.process=uuid(process);require(root.getName().equals(CameraOrientationPlan.ROOT),"ORIENTATION_ROOT");
    if(fresh){require(io.list(root).isEmpty(),"ORIENTATION_CONSUMED");byte[] owner=bytes(json(map("run",CameraOrientationPlan.RUN,"source",source,"apk",apk,"model",CameraProofFrame.MODEL,"recipe",CameraOrientationGeometry.RECIPE,"profileVersion",2)));io.writeNew(new File(root,"owner"),owner);io.syncDirectory(root);append("registry",registry());}validate();
  }
  public static Set<String> names(){Set<String> a=new HashSet<>(Arrays.asList("owner","registry","seal"));for(CameraOrientationPlan.Case c:CameraOrientationPlan.ACTIVE_CASES){a.add(c.id+".intent");a.add(c.id+".terminal");}return a;}
  public static void footprint(File root,CameraProofStore.IO io)throws Exception{List<String> names=io.list(root);require(names.size()<=20,"ORIENTATION_JOURNAL_COUNT");long total=0;int temp=0;for(String name:names){String base=name.endsWith(".new")?name.substring(0,name.length()-4):name;require(names().contains(base),"ORIENTATION_LEAF");if(!base.equals(name))temp++;long size=io.size(new File(root,name));require(size>0&&size<=RECORD,"ORIENTATION_RECORD_CAP");total=Math.addExact(total,size);}require(total<=JOURNAL&&temp<=1,"ORIENTATION_BOOK_CAP");}
  private Map<String,Object> registry(){List<Object> rows=new ArrayList<>();for(CameraOrientationPlan.Case c:CameraOrientationPlan.ACTIVE_CASES)rows.add(map("caseId",c.id,"jobId",c.job,"targetSha256",c.target,"layout",c.layout,"sdkLimit",1));return map("run",CameraOrientationPlan.RUN,"cases",rows,"profileVersion",2,"recipe",CameraOrientationGeometry.RECIPE,"jpegLimit",CameraMatrixPlan.JPEG,"sharedOutputLimit",CameraOrientationPlan.ACTIVE_OUTPUT,"automaticRetakes",0);}
  public byte[] raw(String name)throws Exception{require(names().contains(name),"ORIENTATION_LEAF");return io.read(new File(root,name),RECORD);}
  public boolean has(String name)throws Exception{return io.size(new File(root,name))>=0;}
  public Map<String,Object> read(String name)throws Exception{Map<String,Object> value=parse(raw(name),RECORD);keys(value,"name","ownerSha256","payload","digest");require(name.equals(value.get("name"))&&CameraProofFrame.hash(raw("owner")).equals(value.get("ownerSha256")),"ORIENTATION_OWNER_BINDING");Map<String,Object> base=new TreeMap<>(value);Object digest=base.remove("digest");require(CameraProofFrame.hash(bytes(json(base))).equals(digest),"ORIENTATION_RECORD_HASH");return PhonePortabilityJson.object(value.get("payload"));}
  private void validate()throws Exception{
    footprint(root,io);require(Arrays.equals(raw("owner"),bytes(json(map("run",CameraOrientationPlan.RUN,"source",source,"apk",apk,"model",CameraProofFrame.MODEL,"recipe",CameraOrientationGeometry.RECIPE,"profileVersion",2)))) ,"ORIENTATION_OWNER");
    require(has("registry")&&json(read("registry")).equals(json(registry())),"ORIENTATION_REGISTRY");boolean gap=false,pending=false,failed=false;
    for(CameraOrientationPlan.Case c:CameraOrientationPlan.ACTIVE_CASES){boolean intent=has(c.id+".intent"),terminal=has(c.id+".terminal");require(!terminal||intent,"ORIENTATION_TERMINAL_NO_INTENT");if(intent){require(!gap&&!pending&&!failed,"ORIENTATION_ROW_ORDER");Map<String,Object> q=read(c.id+".intent");keys(q,"caseId","jobId","targetSha256","source","apk","request","requestSha256","nonce","process");require(c.id.equals(q.get("caseId"))&&c.job.equals(q.get("jobId"))&&c.target.equals(q.get("targetSha256"))&&source.equals(q.get("source"))&&apk.equals(q.get("apk"))&&CameraProofFrame.hash(bytes(json(q.get("request")))).equals(q.get("requestSha256")),"ORIENTATION_INTENT");uuid(q.get("nonce"));uuid(q.get("process"));}else gap=true;
      if(terminal){Map<String,Object> t=read(c.id+".terminal");keys(t,"caseId","profileSha256","published","physicalDrainProven");require(c.id.equals(t.get("caseId"))&&t.get("published") instanceof Boolean&&Boolean.FALSE.equals(t.get("physicalDrainProven")),"ORIENTATION_TERMINAL");hash(t.get("profileSha256"));failed=!Boolean.TRUE.equals(t.get("published"));}else if(intent)pending=true;
    }
    if(has("seal")){Map<String,Object> sealed=read("seal");require(json(sealed).equals(json(sealPayload())),"ORIENTATION_SEAL");}
  }
  private void append(String name,Map<String,Object> payload)throws Exception{
    require(names().contains(name)&&!has(name),"ORIENTATION_CONSUMED");Map<String,Object> base=map("name",name,"ownerSha256",CameraProofFrame.hash(raw("owner")),"payload",payload);Map<String,Object> envelope=new TreeMap<>(base);envelope.put("digest",CameraProofFrame.hash(bytes(json(base))));byte[] body=bytes(json(envelope));require(body.length<=RECORD,"ORIENTATION_RECORD_CAP");long total=body.length;for(String n:io.list(root))total+=io.size(new File(root,n));require(total<=JOURNAL&&io.available(root)>=body.length,"ORIENTATION_BOOK_CAP");File stage=new File(root,name+".new");io.writeNew(stage,body);io.publish(stage,new File(root,name));io.syncDirectory(root);
  }
  public synchronized String next()throws Exception{validate();for(CameraOrientationPlan.Case c:CameraOrientationPlan.ACTIVE_CASES){if(!has(c.id+".intent"))return c.id;if(!has(c.id+".terminal"))return "UNRESOLVED";if(!Boolean.TRUE.equals(read(c.id+".terminal").get("published")))return "STOP";}return has("seal")?"SEALED":"COMPLETE";}
  public synchronized void consume(CameraOrientationPlan.Case c,Map<String,Object> request,String nonce)throws Exception{require(next().equals(c.id),"ORIENTATION_ROW_CONSUMED");append(c.id+".intent",map("caseId",c.id,"jobId",c.job,"targetSha256",c.target,"source",source,"apk",apk,"request",request,"requestSha256",CameraProofFrame.hash(bytes(json(request))),"nonce",uuid(nonce),"process",process));validate();}
  public synchronized void terminal(CameraOrientationPlan.Case c,Map<String,byte[]> profile)throws Exception{require(has(c.id+".intent")&&!has(c.id+".terminal"),"ORIENTATION_TERMINAL_CONSUMED");boolean published=profile.keySet().equals(new HashSet<>(CameraEvidenceExport.ROLES));if(published)CameraOrientationArchive.validateProfile(c,profile,source,apk,read(c.id+".intent"));append(c.id+".terminal",map("caseId",c.id,"profileSha256",CameraMatrixStore.profileHash(profile),"published",published,"physicalDrainProven",false));validate();}
  private Map<String,Object> sealPayload()throws Exception{List<Object> rows=new ArrayList<>();for(CameraOrientationPlan.Case c:CameraOrientationPlan.ACTIVE_CASES){require(has(c.id+".terminal")&&Boolean.TRUE.equals(read(c.id+".terminal").get("published")),"ORIENTATION_SEAL_INCOMPLETE");rows.add(map("caseId",c.id,"terminalSha256",CameraProofFrame.hash(raw(c.id+".terminal"))));}return map("run",CameraOrientationPlan.RUN,"cases",rows,"cameraProofAccepted",false);}
  public synchronized void seal()throws Exception{require(next().equals("COMPLETE"),"ORIENTATION_SEAL_STATE");append("seal",sealPayload());validate();}
  public synchronized void exportable(int prefix)throws Exception{validate();require(prefix==1,"ORIENTATION_EXPORT_PREFIX");for(int n=0;n<prefix;n++){CameraOrientationPlan.Case c=CameraOrientationPlan.ACTIVE_CASES.get(n);require(has(c.id+".terminal")&&Boolean.TRUE.equals(read(c.id+".terminal").get("published")),"ORIENTATION_EXPORT_INCOMPLETE");}if(prefix==8)require(has("seal"),"ORIENTATION_EXPORT_UNSEALED");}
  public synchronized Map<String,Object> status()throws Exception{
    String next=next();Map<String,Object> result=map("kind","CAMERA_ORIENTATION_STATUS","run",CameraOrientationPlan.RUN,"next",next,"source",source,"apk",apk,"profileVersion",2,"recipe",CameraOrientationGeometry.RECIPE,"cameraProofAccepted",false);
    CameraOrientationPlan.Case last=null;for(CameraOrientationPlan.Case c:CameraOrientationPlan.ACTIVE_CASES){if(has(c.id+".intent"))last=c;if(c.id.equals(next))result.put("nextJobId",c.job);}
    result.put("lastCase",last==null?null:last.id);result.put("lastJobId",last==null?null:last.job);result.put("lastPublished",last!=null&&has(last.id+".terminal")?read(last.id+".terminal").get("published"):null);return result;
  }
}
